,NULL,1),(225998,37591,'110','#','#','$a Departemen Tenaga Kerja dan Transmigrasi RI',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(225999,37591,'264','#','1','$a Jakarta $b Departemen Tenaga Kerja dan Transmigrasi $c 2009',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226000,37591,'300','#','#','$a viii,112 Halaman: 24 cm.',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226001,37591,'020','#','#','$a -',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226002,37591,'082','#','#','$a 331.124',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226003,37591,'084','#','#','$a 331.124 ANA',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226004,37591,'500','#','#','$a Buku ini disusun oleh Departemen Tenaga Kerja dan Transmigrasi RI, Direktorat Jenderal Pembinaan Penempatan Tenaga Kerja, Direktorat Pengembangan Pasar Kerja (Jakarta, November 2009), dilatarbelakangi oleh kondisi penyerapan tenaga kerja di sektor industri yang meskipun secara absolut sedikit meningkat dari 12,37 juta orang (2007) menjadi 12,55 juta orang (2008), namun komposisinya relatif menurun dari 12,38% menjadi 12,24%, sehingga sektor industri turun ke peringkat keempat dalam penyerapan tenaga kerja—kondisi yang dinilai memprihatinkan mengingat sektor industri seharusnya menjadi penghela perekonomian daerah dan andalan penyerapan tenaga kerja baik kasar maupun terampil dan terdidik; buku ini menyajikan kajian dan analisis untuk mengetahui peluang kesempatan kerja di sektor industri pada masa mendatang dengan menelaah arah kebijakan dan road map pengembangan industri, kondisi dan faktor-faktor yang mempengaruhinya, serta proyeksi kebutuhan dan ketersediaan tenaga kerja di daerah, disusun secara sistematis ke dalam 5 (lima) bab yaitu Pendahuluan, Gambaran Arah Kebijakan dan Road Map Industri Unggulan (mencakup 10 jenis industri agro unggulan seperti pengolahan hasil laut, kakao, karet, furnitur, kelapa sawit, kelapa, kopi, tembakau, buah, dan gula), Identifikasi Rencana Pengembangan Beberapa Industri Unggulan, Analisis Peluang Kesempatan Kerja di Sektor Industri (mencakup proyeksi kebutuhan tenaga kerja, analisis ketersediaan tenaga kerja di daerah berdasarkan strata pendidikan, serta peluang kesempatan kerja berdasarkan analisis jabatan/benchmark kebutuhan tenaga kerja per jenis industri), dan Kesimpulan dan Rekomendasi bagi Departemen Perindustrian, Pemerintah Daerah, Depnakertrans, dan Depdiknas, dengan tujuan menjadi pedoman dan acuan bagi stakeholder serta institusi pendidikan dan pelatihan dalam mengarahkan dan mempersiapkan angkatan kerja agar terjadi keselarasan antara tenaga kerja yang ditawarkan dengan yang dibutuhkan sektor industri.',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226005,37591,'600','0','#','$a Pekerjaan, Lapangan; Kantor penempatan tenaga kerja',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226006,37591,'008','#','#','$a 261022#############################ind##',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226007,37592,'245','#','#','$a Wirata Nomor 48 tahun XIII Triwulan I $c Departemen Tenaga Kerja dan Transmigrasi',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226008,37592,'110','#','#','$a Departemen Tenaga Kerja dan Transmigrasi',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226009,37592,'264','#','1','$a Jakarta $b Departemen Tenaga Kerja dan Transmigrasi $c 2004',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226010,37592,'300','#','#','$a iii, 90 Halaman; 28 cm.',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226011,37592,'020','#','#','$a -',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(226012,37592,'082','#','#','$a 051',0,NULL,'2026-10-22 07:59:43','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(22601