,NULL,1),(230770,38105,'082','#','#','$a 658.31',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230771,38105,'084','#','#','$a 658.31 BAL m',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230772,38105,'500','#','#','$a Buku Memasarkan Diri Dan Karier merupakan panduan praktis dan strategis yang mengulas teknik serta seni personal branding dalam dunia profesional modern. Karya ini membedah cara-cara efektif bagi individu untuk mengidentifikasi nilai unik (unique value proposition) yang mereka miliki, membangun reputasi profesional yang kuat, memanfaatkan jaringan relasi (networking), serta mengoptimalkan berbagai media—termasuk platform digital dan profesional—untuk meningkatkan visibilitas di pasar kerja. Melalui penyajian kerangka kerja yang aplikatif, publikasi ini berfungsi sebagai rujukan esensial bagi para pencari kerja, profesional yang ingin melakukan akselerasi kenaikan jenjang karier, wirausahawan, serta praktisi sumber daya manusia yang mendalami strategi pengembangan kompetensi dan pemasaran tenaga kerja.',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230773,38105,'600','0','#','$a Pegawai -- Pendidikan dan pelatihan',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230774,38105,'008','#','#','$a 261022#############################ind##',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230775,38106,'245','#','#','$a Membuka Potensi Karier $c Ballback, Jane',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230776,38106,'100','0','#','$a Ballback, Jane',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230777,38106,'700','0','#','$a Slater, Jan',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230778,38106,'264','#','1','$a Jakarta $b Lembaga Manajemen PPM dan Penerbit PPM $c 2002',0,NULL,'2026-10-22 07:59:47','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(230779,38106,'300','#','#',