ION',NULL,NULL,NULL,NULL,1),(233228,38364,'245','#','#','$a Studi Kompetisi Sektoral Strategi Pengembangan Tenaga Kerja Sektor Perikanan $c Departemen Tenaga Kerja RI',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233229,38364,'100','0','#','$a Departemen Tenaga Kerja RI',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233230,38364,'264','#','1','$a Jakarta $b Departemen Tenaga Kerja RI $c 1998',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233231,38364,'300','#','#','$a ix, 120 Halaman; 23 cm.',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233232,38364,'020','#','#','$a -',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233233,38364,'082','#','#','$a 639.2',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233234,38364,'084','#','#','$a 639.2 STU',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233235,38364,'500','#','#','$a Merupakan kajian strategis mengenai pemetaan dan proyeksi kebutuhan tenaga kerja terampil di sektor perikanan Indonesia. Penyusunannya bertujuan untuk merumuskan kebijakan perencanaan tenaga kerja berbasis kebutuhan industri (demand-driven) guna menghadapi tantangan globalisasi, perdagangan bebas (AFTA, APEC, WTO), serta mengoptimalkan potensi kelautan nasional yang selama ini belum terkelola secara maksimal. Ruang lingkup isinya mencakup analisis permasalahan Ketenagakerjaan dan permodalan di sektor perikanan laut, evaluasi potensi industri berbasis sumber daya alam (resource-based industry) sebagai penghasil devisa, serta penyusunan proyeksi kebutuhan pelatihan spesifik untuk berbagai jenis pekerjaan, baik di lingkup penangkapan ikan maupun industri pengolahan (khususnya pengalengan ikan). Melalui kajian terstruktur ini, dokumen ini berfungsi sebagai landasan formasi kebijakan pelatihan vokasi, penguatan daya saing SDM perikanan nasional, serta upaya mengurangi ketergantungan pada kapal dan tenaga kerja asing di perairan Indonesia.',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233236,38364,'600','0','#','$a Perikanan',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233237,38364,'008','#','#','$a 261022#############################ind##',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233238,38365,'245','#','#','$a Memacu Pertumbuhan Gurami dengan Benih Unggul, Pakan, dan Sistem Oksigenisasi $c Jangkaru, Zulkifli',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233239,38365,'100','0','#','$a Jangkaru, Zulkifli',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233240,38365,'264','#','1','$a Jakarta $b Penebar Swadaya $c 2007',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233241,38365,'300','#','#','$a iv+92 hlm.; ilus.; 23 cm.',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233242,38365,'020','#','#','$a 979-489-471-0',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233243,38365,'082','#','#','$a 639.31',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233244,38365,'084','#','#','$a 639.31 JAN m',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233245,38365,'600','0','#','$a Perikanan air tawar; Gurami',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233246,38365,'008','#','#','$a 261022#############################ind##',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233247,38366,'245','#','#','$a Biologi Tanah : Ekologi dan Mikrobiologi Tanah $c Hanafiah, Kemas Ali',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233248,38366,'100','0','#','$a Hanafiah, Kemas Ali',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(233249,38366,'700','0','#','$a Anas Iswandi',0,NULL,'2026-10-22 07:59:49','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,