INSERT INTO `catalog_ruas` VALUES (248940,39940,'500','#','#','$a Mismatch di pasar tenaga kerja terjadi di seluruh dunia, baik di negara maju maupun berkembang. Namun, sifat mismatch ini telah berubah selama beberapa tahun terakhir. Penyebab mismatch tradisional adalah rendahnya permintaan tenaga kerja dalam kondisi pasokan tenaga kerja yang tinggi, yang menyebabkan pengangguran, terutama di antara pekerja muda. Akan tetapi, perubahan ekonomi dan perkembangan teknologi telah memunculkan wajah baru dari mismatch — yaitu penganggur terdidik. Seiring dengan semakin banyaknya industri berbasis pengetahuan, permintaan untuk tenaga kerja dengan pendidikan tinggi, teknisi, dan spesialis meningkat. Namun, sistem pendidikan dan pelatihan, oleh sifatnya sendiri dalam pengembangan sumber daya manusia, sering kali tidak cukup fleksibel untuk cepat menyesuaikan diri dengan kebutuhan industri. Akibatnya, pekerja terdidik dengan keahlian tinggi tidak dapat menemukan pekerjaan yang sesuai dengan latar pendidikan mereka karena jenis pekerjaan yang mereka persiapkan mungkin sudah tidak dibutuhkan. Pengangguran di antara mereka meningkat, yang dapat menjadi sumber konflik sosial-politik. Mereka yang berhasil mendapatkan pekerjaan mungkin bekerja pada posisi yang tidak membutuhkan keahlian atau pelatihan mereka, sehingga mismatch dalam bentuk underemployment muncul, yang berpotensi menyebabkan tenaga kerja menjadi kurang bermotivasi dan kurang produktif.\r\n\r\nPerubahan sifat mismatch ini semakin jelas di Asia ketika perekonomian restrukturisasi untuk menghadapai globalisasi, daya saing, dan perkembangan teknologi. Tidak ada solusi cepat karena masalah ini bersifat multifaset. Namun, pemahaman yang lebih baik tentang karakteristik spesifik situasi mismatch akan membantu dalam merumuskan strategi pembangunan ekonomi dan sumber daya manusia yang realistis dan efektif agar pra-kondisi mismatch bisa diminimalkan.\r\n\r\nBuku ini berisi hasil survei APO tentang “Mismatch in Labor Market” yang dilakukan di sembilan negara anggota pada tahun 2000-2001. Tujuan survei tersebut adalah menganalisis jenis-jenis mismatch masa lalu dan sekarang di pasar tenaga kerja di negara-negara tersebut; memahami faktor-faktor penyebab; dan mengusulkan langkah-langkah untuk meminimalkan mismatch tenaga kerja. Didalamnya terdapat analisis terintegrasi mismatch tenaga kerja di Asia oleh Prof. Hiromitsu Muta dan laporan per negara dari ahli-ahli dalam negara-negara peserta: Republik Tiongkok, India, Jepang, Nepal, Filipina, Singapura, Sri Lanka, Thailand, dan Vietnam.',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248941,39940,'600','0','#','$a Ketenagakerjaan; Tenaga Kerja, penyediaan; Pekerjaan, Lapangan; Pasar tenaga kerja',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248942,39940,'008','#','#','$a 261022#############################eng##',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248943,39941,'245','#','#','$a Manajemen Jilid 1 $c James A.F. Stoner',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248944,39941,'100','0','#','$a James A.F. Stoner',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248945,39941,'700','0','#','$a R. Edward Freeman',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248946,39941,'700','0','#','$a Daniel R. Gilbert Jr',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248947,39941,'264','#','1','$a Jakarta $b prenhalindo $c 1996',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248948,39941,'300','#','#','$a xvii+310 hlm.; ilus.; 26 cm.',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248949,39941,'020','#','#','$a 979-8901-04-5',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248950,39941,'082','#','#','$a 658.401 3',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248951,39941,'084','#','#','$a 658.401 3 STO m',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248952,39941,'500','#','#','$a Buku ini memperkenalkan konsep dasar manajemen yang meliputi fungsi-manajemen utama: perencanaan, pengorganisasian, pengarahan (leadership), dan pengendalian (controlling). Penulis menekankan bahwa seorang manajer harus mampu mengaplikasikan keempat fungsi ini secara seimbang untuk mencapai tujuan organisasi secara efektif dan efisien. Selain fungsi, buku ini juga membahas karakteristik seorang manajer, tantangan yang dihadapi dalam lingkungan organisasi, serta pentingnya penggunaan sumber daya – manusia, keuangan, material dan informasi – dalam proses manajerial. Ditujukan bagi mahasiswa dan praktisi awal manajemen, buku ini menyajikan teori dan contoh aplikatif sederhana untuk memperjelas bagaimana proses manajemen dijalankan dalam organisasi.',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248953,39941,'600','0','#','$a Manajemen',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248954,39941,'008','#','#','$a 261022#############################ind##',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248955,39942,'245','#','#','$a Environmental Impact Assessment for Farms: Adoption of Environmental Impact Assessment Methods for On-farm Level Application in Asian and the Pacific $c Asian Productivity Organization',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248956,39942,'110','#','#','$a Asian Productivity Organization',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248957,39942,'264','#','1','$a Tokyo $b Asian Productivity Organization $c 2000',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248958,39942,'300','#','#','$a iii+262 hlm.; 26 cm.',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(248959,39942,'020','#','#','$a 92-83322630',0,NULL,'2026-10-22 08:00:00','SLIMS_MIGRATION',N