,NULL,NULL,1),(258986,41001,'500','#','#','$a Buku ini menyajikan dasar-dasar pemikiran dan ajaran dari gerakan Church of Scientology, menurut pandangan pendirinya, L. Ron Hubbard — menjelaskan konsep-konsep utama Scientology tentang kehidupan, manusia, dan eksistensi spiritual. Versi terjemahan bahasa Indonesia menyajikan ajaran tersebut bagi pembaca Indonesia. Sebagai buku pengantar, ia berfungsi sebagai panduan bagi mereka yang tertarik memahami Scientology secara teoritis dan filosofis.',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258987,41001,'600','0','#','$a Agama; Scientology',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258988,41001,'008','#','#','$a 261022#############################ind##',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258989,41002,'245','#','#','$a Mengenal ilmu komunikasi: metacommunicator is ubiquitous $c Rosmawati H.P.',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258990,41002,'100','0','#','$a Rosmawaty H.P.',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258991,41002,'700','0','#','$a Damang Sarumpaet',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258992,41002,'264','#','1','$a Bandung $b Widya Padjadjaran $c 2010',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258993,41002,'300','#','#','$a ix, 166 hlm.: 25 cm',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258994,41002,'020','#','#','$a 978-602-8323-61-1',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258995,41002,'082','#','#','$a 302.2',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258996,41002,'084','#','#','$a 302.2 ROS m',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258997,41002,'600','0','#','$a Ilmu Komunikasi',0,NULL,'2026-10-22 08:00:15','SLIMS_MIGRATION',NULL,NULL,NULL,NULL,1),(258998,41002,'008','#',