DROP TABLE IF EXISTS `collections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `collections` (
  `ID` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `NomorBarcode` varchar(50) NOT NULL,
  `NoInduk` varchar(50) DEFAULT NULL,
  `Currency` varchar(30) DEFAULT NULL,
  `RFID` varchar(50) DEFAULT NULL,
  `Price` decimal(10,0) DEFAULT NULL,
  `PriceType` varchar(45) DEFAULT NULL,
  `TanggalPengadaan` datetime DEFAULT NULL,
  `CallNumber` varchar(255) DEFAULT NULL,
  `Branch_id` int(11) DEFAULT NULL,
  `Catalog_id` int(11) DEFAULT NULL,
  `Partner_id` int(11) DEFAULT NULL,
  `Location_id` int(11) DEFAULT NULL,
  `Rule_id` int(11) DEFAULT NULL,
  `Category_id` int(11) DEFAULT NULL,
  `Media_id` int(11) DEFAULT NULL,
  `Source_id` int(11) DEFAULT NULL,
  `Status_id` int(11) DEFAULT 9,
  `Location_Library_id` int(11) DEFAULT NULL,
  `Rak` varchar(255) DEFAULT NULL,
  `Keterangan_Sumber` varchar(255) DEFAULT NULL,
  `CreateBy` int(11) DEFAULT NULL,
  `CreateDate` datetime DEFAULT NULL,
  `CreateTerminal` varchar(100) DEFAULT NULL,
  `UpdateBy` int(11) DEFAULT NULL,
  `UpdateDate` datetime DEFAULT NULL,
  `UpdateTerminal` varchar(100) DEFAULT NULL,
  `IsVerified` bit(1) DEFAULT b'0',
  `QUARANTINEDBY` int(11) DEFAULT NULL,
  `QUARANTINEDDATE` date DEFAULT NULL,
  `QUARANTINEDTERMINAL` varchar(100) DEFAULT NULL,
  `ISREFERENSI` bit(1) DEFAULT b'0',
  `EDISISERIAL` varchar(255) DEFAULT NULL,
  `NOJILID` int(11) DEFAULT NULL,
  `TANGGAL_TERBIT_EDISI_SERIAL` date DEFAULT NULL,
  `BAHAN_SERTAAN` varchar(255) DEFAULT NULL,
  `KETERANGAN_LAIN` varchar(255) DEFAULT NULL,
  `TGLENTRYJILID` date DEFAULT NULL,
  `IDJILID` varchar(20) DEFAULT NULL,
  `NOMORPANGGILJILID` varchar(100) DEFAULT NULL,
  `ISOPAC` tinyint(4) DEFAULT 1,
  `ISDRM` int(11) NOT NULL DEFAULT 0,
  `JILIDCREATEBY` int(11) DEFAULT NULL,
  `KIILastUploadDate` datetime DEFAULT NULL,
  `BookingMemberID` varchar(50) DEFAULT NULL,
  `BookingExpiredDate` datetime DEFAULT NULL,
  `IsDeposit` int(11) DEFAULT NULL,
  `NomorDeposit` varchar(21) DEFAULT NULL,
  `ThnTerbitDeposit` int(11) DEFAULT NULL,
  `deposit_ws_ID` int(11) DEFAULT NULL,
  `deposit_kode_wilayah_ID` int(11) DEFAULT NULL,
  `Nomor_Regis` varchar(11) DEFAULT NULL,
  `NomorBarcodeBMN` varchar(50) DEFAULT NULL,
  `IsQUARANTINE` int(11) DEFAULT 0,
  `active` int(11) DEFAULT 1,
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `collections_NomorBarcode` (`NomorBarcode`) USING BTREE,
  KEY `Branch_id` (`Branch_id`) USING BTREE,
  KEY `Catalog_id` (`Catalog_id`) USING BTREE,
  KEY `Partner_id` (`Partner_id`) USING BTREE,
  KEY `Location_id` (`Location_id`) USING BTREE,
  KEY `Rule_id` (`Rule_id`) USING BTREE,
  KEY `Category_id` (`Category_id`) USING BTREE,
  KEY `Media_id` (`Media_id`) USING BTREE,
  KEY `Source_id` (`Source_id`) USING BTREE,
  KEY `collections_callnumber` (`CallNumber`) USING BTREE,
  KEY `collections_status` (`Status_id`) USING BTREE,
  KEY `collections_createby` (`CreateBy`) USING BTREE,
  KEY `collections_updateby` (`UpdateBy`) USING BTREE,
  KEY `collections_quarantinedby` (`QUARANTINEDBY`) USING BTREE,
  KEY `collections_jilidcreateby` (`JILIDCREATEBY`) USING BTREE,
  KEY `collections_idjilid` (`IDJILID`) USING BTREE,
  KEY `collections_currency` (`Currency`) USING BTREE,
  KEY `collections_NoInduk` (`NoInduk`) USING BTREE,
  KEY `collections_edisiserial` (`EDISISERIAL`) USING BTREE,
  KEY `collections_nopanggiljilid` (`NOMORPANGGILJILID`) USING BTREE,
  KEY `collections_jilid1` (`IDJILID`,`NOMORPANGGILJILID`,`Catalog_id`) USING BTREE,
  KEY `collections_tglentryjilid` (`TGLENTRYJILID`) USING BTREE,
  KEY `collections_tanggalpengadaan` (`TanggalPengadaan`) USING BTREE,
  KEY `collections_rfid` (`RFID`) USING BTREE,
  KEY `collections_location_library_idx` (`Location_Library_id`) USING BTREE,
  KEY `collections_kii` (`KIILastUploadDate`) USING BTREE,
  KEY `collections_createdate` (`CreateDate`) USING BTREE,
  KEY `collections_updatedate` (`UpdateDate`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=43757 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
