CREATE TABLE `locations` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `Code` varchar(20) NOT NULL,
  `Name` varchar(255) NOT NULL,
  `Description` varchar(255) DEFAULT NULL,
  `ISPUSTELING` bit(1) DEFAULT b'0',
  `UrlLogo` varchar(100) DEFAULT NULL,
  `IsPrintBarcode` bit(1) DEFAULT b'0',
  `IsGenerateVisitorNumber` bit(1) DEFAULT b'0',
  `IsInformationSought` bit(1) DEFAULT b'0',
  `IsVisitsDestination` bit(1) DEFAULT b'0',
  `LocationLibrary_id` int(11) DEFAULT NULL,
  `CreateBy` int(11) DEFAULT NULL,
  `CreateDate` datetime DEFAULT NULL,
  `CreateTerminal` varchar(100) DEFAULT NULL,
  `UpdateBy` int(11) DEFAULT NULL,
  `UpdateDate` datetime DEFAULT NULL,
  `UpdateTerminal` varchar(100) DEFAULT NULL,
  `KIILastUploadDate` datetime DEFAULT NULL,
  `active` int(11) DEFAULT 1,
  `Branch_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  KEY `locations_createby` (`CreateBy`) USING BTREE,
  KEY `locations_updateby` (`UpdateBy`) USING BTREE,
  KEY `locations_kii` (`KIILastUploadDate`) USING BTREE,
  KEY `locations_createdate` (`CreateDate`) USING BTREE,
  KEY `locations_updatedate` (`UpdateDate`) USING BTREE,
  KEY `locations_loclib_idx` (`LocationLibrary_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=545 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=DYNAMIC;
